// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2025, "8-9", [{"author":"М. Мирошниченко","question":"Соль — в солонке, а перец?","choices":["в перцовке","в перечне","в перечнице","в перчатке","в перчонке."],"key":"В","review":["Соль и перец","Название посуды может указывать на продукт, который в ней держат. Солонка предназначена для соли.","Посуда с отверстиями для молотого перца называется «перечница». «Перцовка» обозначает напиток, а «перечень» — список."]},{"author":"О. Подлесская","question":"В какой фразе <em>уже</em> можно заменить на <em>ещё</em> без существенного изменения смысла фразы?","choices":["Ты уже школьник!","Хорошо, что мама завтра уже приедет.","Уже в древности люди умели добывать огонь.","Этого товара уже нет на складе.","Я уже давно не смотрю телевизор."],"key":"В","review":["«Уже» и «ещё»","Варианты «уже школьник» и «уже нет» сообщают об изменении. Замена на «ещё» приводит к мысли, что прежнее состояние продолжается.","«Уже в древности» и «ещё в древности» одинаково относят умение добывать огонь к очень давнему времени. В обоих случаях это более ранний срок, чем можно было бы ожидать."]},{"author":"Е. Муравенко","question":"Какое слово лишнее по смыслу?","choices":["тарелки","вилки","ложки","гусли","балалайка."],"key":"Б","review":["Лишнее слово","Вспомни не только посуду и приборы. Тарелки бывают ударным инструментом, а на деревянных ложках можно отбивать ритм.","Гусли и балалайка — струнные инструменты. Среди этих пяти названий только «вилки» не обозначают музыкальный инструмент."]},{"author":"А. Сомин","question":"В каком из этих предложений, взятых из текстов в интернете, допущена ошибка?","choices":["Просьба помочь как можно шире распространить эту информацию, дабы желающие смогли попробовать себя в новом качестве!","Мы неделю назад летели с игрушечным котом по кличке Огурчик (дабы ребёнок обожает огурцы).","Я давала впервые противовирусные средства, дабы ребёнок не заболел, — оказывается, это всё бесполезно.","Друзья, собираю информацию, дабы понять: стоит ли на эту идею тратить силы?","Сегодня все кинематографисты, дабы сэкономить бюджет, едут снимать в Восточную Европу."],"key":"Б","review":["Союз «дабы»","«Дабы» можно заменить на «чтобы». С ним называют цель: распространить информацию, чтобы люди узнали о ней, или дать лекарство, чтобы ребёнок не заболел.","Любовь ребёнка к огурцам объясняет причину выбора игрушки. Здесь нужно «потому что ребёнок обожает огурцы». Сочетание «дабы ребёнок обожает» ошибочно."]},{"author":"И. Рубанов","question":"Читаем у Н. С. Лескова в повести «Несмертельный Голован»:\n<em>Панька воззрился и всё на кручу за Орлик смотрит.</em> Тут <em>Орлик</em> — это _____.","choices":["бык","коза","конь","птица","река."],"key":"Д","review":["Орлик у Лескова","Круча — это крутой склон или обрыв. «За Орлик» уточняет, по какую сторону от Орлика смотрит Панька.","Орлик — название реки. Герой смотрит через неё на кручу, расположенную на другом берегу."]},{"author":"М. Мирошниченко","question":"Какое выражение по смыслу отличается от других?","choices":["орёл о двух головах","замок о девяти башнях","дом о пяти окнах","книга о четырёх волшебниках","чудище о трёх хвостах."],"key":"Г","review":["Значения предлога «о»","«Орёл о двух головах» значит «орёл с двумя головами». Замок, дом и чудище тоже описываются через части, которые у них есть.","Четверо волшебников — герои книги, её тема. Поэтому «книга о четырёх волшебниках» употребляет тот же предлог в другом значении."]},{"author":"Н. Ребецкая","question":"В видовой паре глаголы обозначают одно и то же действие, но один относится к совершенному виду, а другой — к несовершенному. В каком примере не представлена видовая пара?","choices":["допросить — допрашивать","заморозить — замораживать","отворить — отваривать","подбодрить — подбадривать","уговорить — уговаривать."],"key":"В","review":["Видовые пары","У видовой пары проверяй и вид, и действие. Допросить и допрашивать — одна работа, рассмотренная как завершённая или длящаяся. Так же устроены пары с «заморозить», «подбодрить» и «уговорить».","«Отворить» значит открыть, например дверь. «Отваривать» значит варить до готовности. Видовые пары — «отворить — отворять» и «отварить — отваривать»."]},{"author":"Е. Бикмаев","question":"В каком слове пропущена не та буква, что в остальных?","choices":["м_лодёжный","м_лодящийся","м_лодушка","м_лодушный","м_лодецкий."],"key":"Г","review":["Гласная в начале слова","«Молодёжный», «молодящийся», «молодушка» и «молодецкий» начинаются на «моло-». В них пропущена буква О.","«Малодушный» связано с сочетанием «мало духа». Оно означает «недостаточно смелый». Здесь первой гласной будет А."]},{"author":"А. Сомин","question":"<em>Мы же не спеша, немного поп_в под дождик, доехали до границы.</em>\n<em>Ещё немного поп_в — теперь уже повеселее, — девушки принялись прощаться до завтра.</em> (А. Посняков)\n<em>Мочить одежду у меня желания не было, поэтому, умывшись, помыв руки и немного поп_в, я отошла в сторону.</em> (Ю. Схейбал)\nКакие гласные надо вставить на месте пропусков?","choices":["и, а, е","а, е, и","е, и, а","а, и, е","и, е, а."],"key":"Б","review":["Три похожих пропуска","В первом предложении люди угодили под дождик, то есть попали под него. Пишем «попав».","Девушки сначала пели и только потом стали прощаться, поэтому «попев». В последнем примере рассказчица выпила воды, поэтому «попив». Буквы идут в порядке А, Е, И."]},{"author":"А. Пиперски","question":"Даны пять названий городов России по-китайски:\n萨拉托夫, 基洛夫, 托木斯克, 萨马拉, 伊热夫斯克.\nВыберите вариант ответа, в котором они перечислены в том же порядке:","choices":["Киров, Самара, Саратов, Ижевск, Томск","Ижевск, Томск, Самара, Киров, Саратов","Саратов, Киров, Томск, Самара, Ижевск","Самара, Томск, Ижевск, Киров, Саратов","Самара, Ижевск, Киров, Саратов, Томск."],"key":"В","review":["Города по-китайски","В названиях 托木斯克 и 伊热夫斯克 общая концовка 斯克 передаёт «ск». Среди русских названий на «ск» заканчиваются Томск и Ижевск. Более короткое 托木斯克 передаёт «Томск».","Первый и четвёртый варианты записи начинаются с 萨, как «Саратов» и «Самара» с «Са». У первой записи конец 托夫 передаёт «тов». Остаётся 基洛夫 — «Киров». Получаем Саратов, Киров, Томск, Самара, Ижевск."]},{"author":"И. Иткин","question":"<em>Почта, почти, почту, почтой.</em> Ответьте максимально точно: сколько здесь слов каких частей речи?","choices":["4 существительных","3 существительных и 1 наречие","4 существительных и 1 наречие","3 существительных и 2 глагола","3 существительных, 2 глагола и 1 наречие."],"key":"Д","review":["Почта, почти, почту","«Почта», «почту» и «почтой» — три падежные формы существительного. В выражении «почти готово» слово «почти» — наречие.","У глагола «почтить» есть формы «почти» и «почту»: «почти память» и «я почту память». Итого три формы существительного, две глагольные и одна наречная."]},{"author":"С. Дьяченко","question":"Какой глагол в одном из русских диалектов обозначает игру на некотором музыкальном инструменте?","choices":["бормотать","бубнить","ворчать","лепетать","тараторить."],"key":"Б","review":["Глагол и инструмент","Поищи глагол, в котором слышится название музыкального инструмента. В слове «бубнить» легко узнать «бубен».","В диалекте «бубнить» значит играть на бубне. В литературном языке тем же словом обычно называют тихое монотонное говорение."]},{"author":"А. Сомин","question":"У какого из этих слов при склонении происходит изменение, которого нет у других?","choices":["кровь","церковь","свекровь","бровь","морковь."],"key":"Б","review":["Слово при склонении","Поставь слова в родительный падеж. Получаем «крови», «церкви», «свекрови», «брови» и «моркови».","В паре «церковь — церкви» исчезает О перед В. У остальных слов эта гласная сохраняется."]},{"author":"Л. Фёдорова","question":"Какое слово образовано не совсем так, как остальные?","choices":["ловушка","вертушка","веснушка","игрушка","хлопушка."],"key":"В","review":["Как образованы слова","«Ловушка» помогает ловить, «вертушка» вертится, «игрушкой» играют, а «хлопушка» хлопает. Можно найти исходный глагол для каждого названия.","У «веснушки» исходное слово — существительное «весна». Это единственное название, образованное от существительного."]},{"author":"Л. Фёдорова","question":"Какое из слов отличается от остальных по смыслу второго компонента?","choices":["градоначальник","военачальник","родоначальник","во всех словах второй компонент имеет одинаковый смысл","во всех словах второй компонент имеет различные смыслы."],"key":"В","review":["Вторая часть сложного слова","Градоначальник управляет городом, военачальник командует войском. У обоих «начальник» значит «руководитель».","Родоначальник стоит у начала рода, направления или обычая. Он основатель или первый представитель, поэтому в этом слове второй компонент имеет другой смысл."]},{"author":"И. Рубанов","question":"<em>Чай, чая, чаю.</em> Что из этого могло быть пропущено во фразе <em>Купи ещё ____</em>?","choices":["только чаю","только чай","только чая","только чаю или чая","все три."],"key":"Д","review":["Покупка чая","Можно попросить «Купи ещё чай, а не кофе». Здесь «чай» называет то, что надо купить, и стоит в винительном падеже.","Если речь о некотором количестве, естественны «Купи ещё чая» и «Купи ещё чаю». Обе формы допустимы. Подходят все три варианта."]},{"author":"А. Остроумова","question":"В какой паре слова соотносятся не так, как в остальных?","choices":["надёжно — безнадёжно","толково — бестолково","радостно — безрадостно","спорно — бесспорно","полезно — бесполезно."],"key":"А","review":["Значения слов с «без-»","У «бестолково», «безрадостно», «бесспорно» и «бесполезно» значение связано с отсутствием соответственно толка, радости, спора и пользы.","«Надёжно» означает «верно, безопасно, без риска», а «безнадёжно» — «без надежды». Прямой антоним «надёжно» — «ненадёжно». Поэтому эта пара отличается."]},{"author":"А. Сомин","question":"В одном из сочинских отелей есть спа-комплекс с остроумным названием. Как он называется?","choices":["LABI","PUNE","NELI","SIBO","TOSI."],"key":"Г","review":["Название сочинского спа","Попробуй прочитать каждое название после слова «спа». В задаче важно звучание всего сочетания.","«SPA SIBO» звучит как «спасибо». Так название процедуры стало первой частью словесной игры."]},{"author":"А. Сомин","question":"Какая из этих последовательностей может встретиться в правильно написанном тексте в раздельном написании (без дефиса)?","choices":["по-русски","во-вторых","юго-запад","из-за стола","опять-таки."],"key":"Б","review":["Дефис или пробел","В выражении «во-вторых» дефис нужен, когда мы перечисляем доводы. Но «во» бывает и обычным предлогом, а «вторых» — формой порядкового числительного.","Например, можно написать «Во вторых классах появились новые учебники». Предлог и числительное здесь пишутся раздельно."]},{"author":"А. Леонтьева","question":"Из личной переписки:\n«Представляешь, Знайка, вчера я в твоей новой книжке увидел слово <em>промокнул</em>! Но учитель нам всегда говорил, что в прошедшем времени у глаголов на <em>-нуть</em>: <em>замёрзнуть, промокнуть, озябнуть</em> — суффикс <em>-ну-</em> исчезает. Кто ошибся, ты или учитель?»\n«Незнайка, твой учитель совершенно прав, но и форма, которую ты видел у меня в книжке, правильная. Дело тут __________ у глагола <em>промокнуть</em>».\nЗаполните пропуск.","choices":["в количестве слогов","в чередовании гласных","в виде","в месте ударения","иногда ошибается даже Знайка — форма промокнул неправильная."],"key":"Г","review":["Два глагола «промокнуть»","«Промо́кнуть под дождём» значит стать мокрым. В прошедшем времени получается «промо́к», как «замёрз» и «озяб».","«Промокну́ть салфеткой» значит убрать влагу. Здесь говорят «промокну́л». Два глагола различаются ударением и значением."]},{"author":"С. Переверзева","question":"Какую фразу можно понять двумя разными способами?","choices":["Состарившись, тётушка совсем оглохла.","Войдя в комнату, он зажёг свет.","Извинившись, Аня поспешно ушла.","Увидев больного, медсестра пожалела его.","Влюбившись, ты совершил большую глупость."],"key":"Д","review":["Два смысла одной фразы","В сочетании с деепричастием основной глагол может обозначать отдельное действие, которое произошло позднее. Прочитай так вариант о влюблённости.","Глупостью могло оказаться само решение влюбиться или другой поступок, совершённый после этого. Фраза допускает оба понимания."]},{"author":"А. Сомин","question":"В дагестанских языках много пространственных падежей. Например, падеж инэссив обозначает нахождение внутри чего-то (например, ‘в доме’), адэссив — возле чего-то (‘возле дома’), а контэссив — вплотную к чему-то (‘вплотную к дому’). А что обозначают падежи суперэссив, постэссив и субэссив (на примере слова со значением ‘дом’)?","choices":["под домом; за домом; над домом","через дом; под домом; за домом","на доме; за домом, под домом","над домом; под домом; за домом","за домом; через дом; над домом."],"key":"В","review":["Три пространственных падежа","Часть «эссив» в названиях из вопроса относится к положению предмета. Смысл положения уточняют первые части.","«Супер-» указывает на поверхность или верх, «пост-» — на положение позади, «суб-» — под чем-то. Получаем «на доме», «за домом», «под домом»."]},{"author":"Е. Муравенко","question":"Какое словосочетание устроено не совсем так, как остальные?","choices":["закадычный друг","заклятый враг","кромешная тьма","трескучий мороз","бесподобная песня."],"key":"Д","review":["Устойчивые сочетания","«Закадычный друг», «заклятый враг», «кромешная тьма» и «трескучий мороз» — привычные устойчивые сочетания. Прилагательные здесь тесно связаны с существительными.","«Бесподобная» значит «необыкновенно хорошая». Так можно назвать песню, игру, пьесу или шутку. Сочетание свободное."]},{"author":"Н. Ребецкая","question":"За словом свет скрывается два омонима: 1) ‘освещение’ и 2) ‘мир, земля, люди’. В каком ряду производные от свет относятся только к одному из омонимов?","choices":["светопреставление, несусветный, светский","беспросветный, просветление, старосветский","засветить, великосветский, светлоголовый","светскость, осветить, световой","светлячок, по-светски, рассвет."],"key":"А","review":["Два значения слова «свет»","Сравни «свет лампы» и «объехать весь свет». В одних словах сохраняется значение освещения, в других — идея мира или общества.","«Светопреставление» — конец света, «несусветный» — выходящий за пределы мыслимого, «светский» связан с обществом. Все три слова первого ряда относятся к «свету» как миру или обществу."]},{"author":"М. Рубинштейн","question":"Персонаж одной повести — иностранец, не очень хорошо говорящий по-русски. Он произносит тост в гостях, но делает маленькую ошибку в одном слове и в результате желает хозяйке, чтобы её дом был __________.","choices":["полная чашка","полная ложка","полная кружка","полная тарелка","полная ерунда."],"key":"А","review":["Пожелание хозяевам","Есть устойчивое пожелание «чтобы дом был полной чашей». Оно означает, чтобы в доме был достаток.","Герой употребил похожее слово «чашка» вместо «чаша». Получилось «полная чашка»."]},{"author":"А. Сомин","question":"Белорусский язык — близкий родственник русского, но по правилам белорусской орфографии безударное о записывается как а, например: вада ‘вода’. Одно из белорусских слов состоит из шести букв, три из которых — а, а другие три — _.","choices":["т","б","в","н","п."],"key":"Б","review":["Слово из двух букв","Поищи русское слово из шести букв с повторяющимися согласными. В слове «баобаб» три Б, две А и одна О.","В безударной позиции вместо О по-белорусски пишется А. Получается «баабаб»: три А и три Б."]},{"author":"П. Долгополов","question":"Какой из глаголов может восприниматься как глагол несовершенного вида?","choices":["сыграть","спеть","сплясать","нарисовать","сочинить."],"key":"Б","review":["Два смысла глагола «спеть»","Если речь о песне, «спеть» обозначает завершённое действие. Но есть глагол с тем же написанием о созревании плодов.","«Яблоки начинают спеть» значит «начинают созревать». Здесь «спеть» несовершенного вида, что и позволяет выбрать его среди пяти глаголов."]},{"author":"Б. Иомдин","question":"Какое географическое название заканчивается не совсем так, как остальные?","choices":["Лап…","Зе…","Ир…","Шот…","Фин…."],"key":"Д","review":["Названия земель","Восстанови названия: Лапландия, Зеландия, Ирландия, Шотландия и Финляндия.","У первых четырёх имеется конец «-ландия», где после Л стоит А. В названии «Финляндия» после Л стоит Я."]},{"author":"Л. Зайдельман","question":"В песне группы «Зимовье Зверей» есть такие строки:\n<em>Ночи без ________,\nГлухие мужские ночи.</em>\nЧто пропущено?","choices":["мягких знаков","прошедшего времени","двоеточий","освещения","женского рода."],"key":"А","review":["Ночи из песни","В единственном числе «ночь» — существительное женского рода с Ь после шипящего. Сравни мужской род: «меч», «плач», «ключ».","Образ «мужских ночей» играет на различии этих написаний. Из вариантов с ним сочетается «ночи без мягких знаков»."]},{"author":"А. Пиперски","question":"Даны шесть геометрических фигур и названия трёх из них по-турецки. Заполните пропуски.\nПримечание: ç = ч, ş = ш, ü = ю в слове <em>тюль</em>.","choices":["eşkenar dörtgen, ikizkenar dörtgen, dikyamuk","dikdörtgen, ikizkenar dörtgen, eşkenar yamuk","eşkenar dörtgen, dikdörtgen, ikizkenar yamuk","ikizkenar dörtgen, eşkenar dörtgen, dikyamuk","dikdörtgen, eşkenar dörtgen, ikizkenar yamuk."],"key":"Д","review":["Фигуры по-турецки","Во всех названиях первой строки есть «üçgen» — «треугольник». По трём рисункам устанавливаем значения: «eşkenar» — с равными сторонами, «ikizkenar» — с двумя равными боковыми сторонами, «dik» — прямой.","Внизу прямоугольник требует «dik», ромб — «eşkenar», равнобокая трапеция — «ikizkenar». В этом порядке части стоят только в варианте Д."],"figure":{"condition":{"src":"assets/medvezhonok/2025/8-9-30.svg","width":600,"height":246,"pixelWidth":600,"pixelHeight":246,"alt":"Наверху три треугольника. Под равносторонним написано eşkenar üçgen, под равнобедренным ikizkenar üçgen, под прямоугольным dik üçgen. Внизу прямоугольник, ромб и равнобокая трапеция. Их названия нужно выбрать."}}}], {"year":2025,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2025-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
